import { Source } from './source';
import { mapEvent } from './mapper';

export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}

  /**
   * Streams mapped records from a single lease.
   *
   * Guarantees:
   * - The lease is not opened until the first `next()` call; returning an
   *   unopened generator opens and closes nothing.
   * - No read-ahead: every `next()` performs exactly one read (the final,
   *   exhaustion-establishing read included).
   * - The lease is closed exactly once on every exit path: normal exhaustion,
   *   consumer break/return, source read failure, mapper failure, or a
   *   consumer-injected throw.
   * - If close fails while another exception is already propagating (read,
   *   mapper or injected), the original exception wins; on all other paths a
   *   close failure is propagated.
   */
  async *stream(): AsyncGenerator<string> {
    let lease: Lease | null = null;
    try {
      for (;;) {
        if (lease === null) {
          lease = await this.source.open();
        }
        const value = await lease.read();
        if (value === null) {
          break;
        }
        yield this.mapper(value);
      }
    } catch (error) {
      // The body failed: open/read failure, mapper failure or a
      // consumer-injected throw. Close the lease if one was opened, but
      // preserve the original error even when closing also fails.
      const failedLease = lease;
      lease = null;
      if (failedLease !== null) {
        try {
          await failedLease.close();
        } catch {
          // Swallowed on purpose: the original error takes precedence.
        }
      }
      throw error;
    } finally {
      // Runs on normal exhaustion and on consumer break/return (the error path
      // above already closed and rethrew, leaving `lease` null). Here there is
      // no in-flight exception, so a close failure must propagate.
      const openLease = lease;
      lease = null;
      if (openLease !== null) {
        await openLease.close();
      }
    }
  }
}
