const assert = require('node:assert/strict');

const { EventService } = require('../.build/service');
const { mapEvent } = require('../.build/mapper');

// Build a Source (see src/source.ts) whose lease reads from a script of
// outcomes: plain strings are values, `null` ends the stream, Error instances
// are thrown from read().
function makeSource({ script = [], failClose = null, openError = null } = {}) {
  const state = { opens: 0, reads: 0, closes: 0 };
  const source = {
    async open() {
      state.opens++;
      if (openError) throw openError;
      const outcomes = script.slice();
      return {
        async read() {
          state.reads++;
          const next = outcomes.shift();
          if (next instanceof Error) throw next;
          return next === undefined ? null : next;
        },
        async close() {
          state.closes++;
          if (failClose) throw failClose;
        },
      };
    },
  };
  return { source, state };
}

async function collect(iterable) {
  const found = [];
  for await (const value of iterable) found.push(value);
  return found;
}

async function main() {
  // Normal exhaustion: mapped in order, one open, one read per next()
  // (including the read establishing exhaustion), exactly one close.
  {
    const { source, state } = makeSource({ script: ['a', 'b'] });
    const found = await collect(new EventService(source).stream());
    assert.deepEqual(found, ['A', 'B']);
    assert.deepEqual(state, { opens: 1, reads: 3, closes: 1 });
  }

  // Returning an unopened generator must not open or close anything.
  {
    const { source, state } = makeSource({ script: ['a'] });
    const gen = new EventService(source).stream();
    await gen.return();
    assert.deepEqual(state, { opens: 0, reads: 0, closes: 0 });
  }

  // No read-ahead: breaking after the first record performs a single read,
  // and the lease is closed exactly once.
  {
    const { source, state } = makeSource({ script: ['a', 'b'] });
    const found = [];
    for await (const value of new EventService(source).stream()) {
      found.push(value);
      break;
    }
    assert.deepEqual(found, ['A']);
    assert.deepEqual(state, { opens: 1, reads: 1, closes: 1 });
  }

  // Explicit return() mid-stream closes exactly once, with no extra read.
  {
    const { source, state } = makeSource({ script: ['a', 'b'] });
    const gen = new EventService(source).stream();
    assert.equal((await gen.next()).value, 'A');
    const ended = await gen.return();
    assert.equal(ended.done, true);
    assert.deepEqual(state, { opens: 1, reads: 1, closes: 1 });
  }

  // Source read failure: lease closed exactly once and the read error
  // propagates; a close failure must not mask it.
  {
    const readError = new Error('read blew up');
    const { source, state } = makeSource({ script: ['a', readError], failClose: new Error('close blew up') });
    await assert.rejects(collect(new EventService(source).stream()), readError);
    assert.deepEqual(state, { opens: 1, reads: 2, closes: 1 });
  }

  // Read failure with a well-behaved close still propagates the read error.
  {
    const readError = new Error('read blew up');
    const { source, state } = makeSource({ script: [readError] });
    await assert.rejects(collect(new EventService(source).stream()), readError);
    assert.deepEqual(state, { opens: 1, reads: 1, closes: 1 });
  }

  // Mapper failure: closed exactly once, mapper error propagates even when
  // close also fails.
  {
    const mapperError = new Error('mapper blew up');
    const { source, state } = makeSource({ script: ['a'], failClose: new Error('close blew up') });
    await assert.rejects(collect(new EventService(source, () => { throw mapperError; }).stream()), mapperError);
    assert.deepEqual(state, { opens: 1, reads: 1, closes: 1 });
  }

  // Consumer-injected throw: closed exactly once, the injected error
  // propagates even when close also fails.
  {
    const injected = new Error('injected');
    const { source, state } = makeSource({ script: ['a', 'b'], failClose: new Error('close blew up') });
    const gen = new EventService(source).stream();
    assert.equal((await gen.next()).value, 'A');
    await assert.rejects(gen.throw(injected), injected);
    assert.deepEqual(state, { opens: 1, reads: 1, closes: 1 });
  }

  // Close failure on normal exhaustion is propagated.
  {
    const closeError = new Error('close blew up');
    const { source, state } = makeSource({ script: ['a'], failClose: closeError });
    await assert.rejects(collect(new EventService(source).stream()), closeError);
    assert.deepEqual(state, { opens: 1, reads: 2, closes: 1 });
  }

  // Close failure on consumer return is propagated through return().
  {
    const closeError = new Error('close blew up');
    const { source, state } = makeSource({ script: ['a'], failClose: closeError });
    const gen = new EventService(source).stream();
    assert.equal((await gen.next()).value, 'A');
    await assert.rejects(gen.return(), closeError);
    assert.deepEqual(state, { opens: 1, reads: 1, closes: 1 });
  }

  // Open failure: nothing to close, open error propagates.
  {
    const openError = new Error('open blew up');
    const { source, state } = makeSource({ openError, failClose: new Error('close blew up') });
    await assert.rejects(collect(new EventService(source).stream()), openError);
    assert.deepEqual(state, { opens: 1, reads: 0, closes: 0 });
  }

  // Exhaustion read yields no value and a later next() stays done without
  // re-opening or re-reading.
  {
    const { source, state } = makeSource({ script: [] });
    const gen = new EventService(source).stream();
    const first = await gen.next();
    assert.equal(first.done, true);
    const second = await gen.next();
    assert.equal(second.done, true);
    assert.deepEqual(state, { opens: 1, reads: 1, closes: 1 });
  }

  // Default mapper is still mapEvent.
  {
    const { source } = makeSource({ script: ['x'] });
    const found = await collect(new EventService(source).stream());
    assert.deepEqual(found, [mapEvent('x')]);
  }

  return 'checks/stream.cjs passed';
}

